query.base:
TS metrics-gcp.bigquery.otel-*
// Lowest-latency cost signal: statement_scanned_bytes_billed (DELTA, ~3 minute publish delay).
// The rolling window is the rule look-back (24 hours by default).
| WHERE resource.attributes.gcp.resource_type == "bigquery_project"
  AND `metrics.bigquery.googleapis.com/query/statement_scanned_bytes_billed` IS NOT NULL
// DELTA amounts are additive: SUM is exact across fragmented TSIDs, locations, priorities and statement types
| STATS bytes_billed = SUM(SUM_OVER_TIME(`metrics.bigquery.googleapis.com/query/statement_scanned_bytes_billed`)),
        select_bytes_billed = SUM(SUM_OVER_TIME(`metrics.bigquery.googleapis.com/query/statement_scanned_bytes_billed`)) WHERE attributes.statement_type == "select"
    BY resource.attributes.project_id
// Customise: per-project rolling 24h budget in bytes billed (default 10 TiB = 10 * 1099511627776).
// To estimate cost, multiply TiB billed by your on-demand price per TiB.
| EVAL budget_bytes = 10 * 1099511627776
